#' Single Variable Quality Check
#'
#' 
#' @param data .
#' @param var .
#' @param showOutliers .
#' @param outlierTransform .
#' @param rareCategoryThreshold .
#' @param cvMinMean .
#' @param showDistribution .
#' @param showDuplicates .
#' @param showPatterns .
#' @param showSummary .
#' @param showPlot .
#' @param showInteractive .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$overview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$distribution} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$methods} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$outliers} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$frequencies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$patterns} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$scope} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$screeningFlag} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overview$asDF}
#'
#' \code{as.data.frame(results$overview)}
#'
#' @export
pycheckdata <- function(
    data,
    var = NULL,
    showOutliers = TRUE,
    outlierTransform = "none",
    rareCategoryThreshold = 5,
    cvMinMean = 0.01,
    showDistribution = FALSE,
    showDuplicates = FALSE,
    showPatterns = FALSE,
    showSummary = FALSE,
    showPlot = TRUE,
    showInteractive = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pycheckdata requires jmvcore to be installed (restart may be required)")

    if ( ! missing(var)) var <- jmvcore::resolveQuo(jmvcore::enquo(var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(var), var, NULL))


    options <- pycheckdataOptions$new(
        var = var,
        showOutliers = showOutliers,
        outlierTransform = outlierTransform,
        rareCategoryThreshold = rareCategoryThreshold,
        cvMinMean = cvMinMean,
        showDistribution = showDistribution,
        showDuplicates = showDuplicates,
        showPatterns = showPatterns,
        showSummary = showSummary,
        showPlot = showPlot,
        showInteractive = showInteractive,
        showConsole = showConsole)

    analysis <- pycheckdataClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

